options.onCreated:
const s = this.vueState
const field = this
s.tran = null   // visit tran ที่เลือกจากคิว — เซ็ตโดยปุ่ม EMR / onMounted

s.pt = () => (s.tran && s.tran.vid && s.tran.vid.pid) || {}
s.ptName = () => {
  const p = s.pt()
  return ((p.prename && p.prename.label) || '') + (p.p_fname || '') + ' ' + (p.p_lname || '')
}
s.picUrl = () => {
  const p = s.pt()
  return (Array.isArray(p.p_pic) && p.p_pic[0] && p.p_pic[0].url) || ''
}
s.initial = () => { const p = s.pt(); return p.p_fname ? p.p_fname.charAt(0) : '?' }
s.genderLabel = () => ({ '1': 'ชาย', '2': 'หญิง' })[s.pt().p_gender] || '-'
s.aboLabel = () => {
  const m = { '1': 'A', '2': 'B', '3': 'AB', '4': 'O', '5': 'ไม่ทราบ', '9': 'ไม่ทราบ' }
  const p = s.pt()
  return m[p.p_abogroup] || p.p_abogroup || '-'
}
// ประเภทบริการ (visit_type บน Visit form) — ค่าจาก builder: 1=ตรวจสุขภาพ, 2=ตรวจตามนัด, 3=รับส่งต่อ, 4=ตรวจรักษา, 5=อื่นๆ
s.visitTypeMap = { '1': 'ตรวจสุขภาพ', '2': 'ตรวจตามนัด', '3': 'รับส่งต่อ', '4': 'ตรวจรักษา', '5': 'อื่นๆ' }
s.serviceTypeLabel = () => {
  const v = s.tran && s.tran.vid && s.tran.vid.visit_type
  return v ? (s.visitTypeMap[v] || v) : ''
}
s.visitTime = () => {
  const t = s.tran && s.tran.checkin_at
  if (!t) return '-'
  const d = field.dayjs(t)
  return d.format('DD/MM/') + (d.year() + 543) + d.format(' HH:mm')   // ค.ศ. → พ.ศ. (+543)
}

// เปิดฟอร์มผู้ป่วย (PERSON) — id ผู้ป่วยอยู่ที่ vid.xtbxlv1_xfx_id (= pid.value ของ visit)
s.openPatient = () => {
  const pidId = s.tran && s.tran.vid && s.tran.vid.xtbxlv1_xfx_id
  if (!pidId) { field.alert('ไม่พบ id ผู้ป่วยใน visit นี้', 'warning'); return }
  const form = field.getFormRef()
  form.openForm('6a37d3bd4cfbfdbe257fc912', String(pidId), '', null, {
    afterSaveCallback: (saved) => {
      form.subFormClose()
      if (!saved) return
      const p = s.tran.vid.pid
      if (p) {
        ['hn', 'prename', 'p_fname', 'p_lname', 'p_gender', 'age', 'p_abogroup', 'birth_date', 'p_pic']
          .forEach((k) => { if (k in saved) p[k] = saved[k] })
      }
      // sync allergy_tags ลง visit_tran จริง → ws เด้งจอคิว + เอา tags กลับมาอัปเดตการ์ด
      form.userState.runProcess('6a50cc20e97c6d6bbf111ce0', { person_id: String(s.tran.vid.xtbxlv1_xfx_id), sync_allergy: true }, (res) => {
        const d = res.data || {}
        if (d.success && 'allergy_tags' in d) s.tran.allergy_tags = d.allergy_tags || []
      }, (err) => field.alert('sync การแพ้ไม่สำเร็จ: ' + ((err && err.message) || err), 'error'))
    }

  })
}

s.bmiRec = null   // record BMI ล่าสุดของ visit นี้

s.loadBmi = () => {
  s.bmiRec = null
  const visitId = s.tran && s.tran.vid && s.tran.vid.value
  if (!visitId) return
  field.getFormRef().userState.crudGetAll({
    sdProvider: {
      providerId: '6a4689ef39179670f85ba2a2',   // ฟอร์ม BMI
      providerType: 'FORM',
      params: { vid: String(visitId) },
      options: {
        where: "`vid.value` = CONVERT(:vid, 'objectId')",
        orderBy: [{ column: 'created_at', sort: 'DESC' }],
        limit: 1,
        page: 1
      }

    },
    totalEnable: false
  }, (res) => { s.bmiRec = (res.data && res.data[0]) || null })
}

// เซ็ตคนไข้ + โหลด BMI — ให้ปุ่ม EMR / onMounted เรียกตัวนี้แทนเซ็ต tran ตรง
s.setTran = (row) => {
  s.tran = row; s.loadBmi(); s.loadVs(); s.tickExam()
  // ยังไม่เลือกผู้ป่วย → ซ่อนโซน SOAP ทั้งแถบ (container hide แค่ซ่อน ไม่ล้างค่า field)
  const box = field.getFieldRef('emr_box')
  if (box) { row ? box.show() : box.hide() }
  // เซ็ต visit id ลง field vid + refresh consult — หน่วง 1 tick กันเคส mount แรกที่ field ยังไม่ register
    // เซ็ต visit id ลง field vid + refresh consult + registry — หน่วง 1 tick กันเคส mount แรกที่ field ยังไม่ register
  setTimeout(() => {
    const vidVal = (row && row.vid && row.vid.value) ? String(row.vid.value) : ''
    const f = field.getFieldRef('vid')
    if (f) f.setValue(vidVal)
    const cs = field.getFieldRef('consult_box')
    if (cs && cs.vueState && cs.vueState.load) cs.vueState.load(vidVal || null)

      const cbn = field.getFieldRef('consult_banner')
      if (cbn) {
        if (cbn.vueState && cbn.vueState.load) cbn.vueState.load(row || null)
        // ซ่อน field ทั้งอันถ้าไม่มี consult ฝั่งรับ (clinic===unit_to) — กันช่องว่าง
        const ci = row && row.consult_info
        const showBanner = !!(ci && ci.clinic && row.unit_to && String(ci.clinic) === String(row.unit_to.value))
        showBanner ? cbn.show() : cbn.hide()
      }


    // refresh Disease Registry — person id อยู่ที่ vid.xtbxlv1_xfx_id (= pid.value ของ visit)
    const rg = field.getFieldRef('registry_card')
    if (rg && rg.vueState && rg.vueState.load) {
      const personId = (row && row.vid && row.vid.xtbxlv1_xfx_id) ? String(row.vid.xtbxlv1_xfx_id) : null
      rg.vueState.load(personId, (row && row.vid && row.vid.pid) || null, vidVal || null)
    }

    // ── วางต่อจากบล็อก registry_card ในตัว setTimeout เดิม ──────────────────
    // refresh การ์ดใบสั่งยา — ส่ง tran ไปด้วย เพราะการ์ดใช้ประกอบ patient context ตอนเปิดจอสั่งยา
    const oc = field.getFieldRef('order_card');
    if (oc && oc.vueState && oc.vueState.ordLoad) {
    	oc.vueState.ordLoad(vidVal || null, row || null);
    }
  }, 0)

}



// เปิดฟอร์ม BMI — dataId null = เพิ่มใหม่ (parent = visit), มีค่า = แก้ record เดิม
s.openBmi = (dataId) => {
  const visitId = s.tran && s.tran.vid && s.tran.vid.value
  if (!visitId) { field.alert('ไม่พบ visit', 'warning'); return }
  const form = field.getFormRef()
  form.openForm('6a4689ef39179670f85ba2a2', dataId ? String(dataId) : null, String(visitId), null, {
    afterSaveCallback: () => { form.subFormClose(); s.loadBmi() }
  })
}

s.vsRec = null   // Vital Sign ล่าสุดของ visit นี้

// เกณฑ์ปกติ (ผู้ใหญ่) — นอกช่วง min-max = เตือนเหลือง (is-warning), แตะ dMin/dMax = แดง (is-danger)
// ปรับตัวเลขได้ที่นี่จุดเดียว
s.vsRules = {
  bp_h:  { min: 90, max: 140, dMin: 80, dMax: 180 },
  bp_l:  { min: 60, max: 90,  dMax: 110 },
  pulse: { min: 60, max: 100, dMin: 40, dMax: 130 },
  temp:  { min: 36, max: 37.4, dMin: 35, dMax: 38.5 },
  rr:    { min: 12, max: 20,  dMin: 8,  dMax: 30 }
}
s.vsClassForRec = (rec, name) => {
  const r = s.vsRules[name]
  const v = rec ? rec[name] : null
  if (!r || v == null || v === '') return ''
  if ((r.dMin != null && v <= r.dMin) || (r.dMax != null && v >= r.dMax)) return 'is-danger'
  if (v < r.min || v > r.max) return 'is-warning'
  return ''
}
s.vsClass = (name) => s.vsClassForRec(s.vsRec, name)
// BP ใช้ระดับที่แย่กว่าระหว่างตัวบน/ตัวล่าง
s.bpClassForRec = (rec) => {
  const c = [s.vsClassForRec(rec, 'bp_h'), s.vsClassForRec(rec, 'bp_l')]
  return c.indexOf('is-danger') >= 0 ? 'is-danger' : (c.indexOf('is-warning') >= 0 ? 'is-warning' : '')
}
s.bpClass = () => s.bpClassForRec(s.vsRec)
// สีเซลล์ตาราง VS ตาม threshold เดียวกับการ์ดสรุป — inline style (ไม่พึ่ง CSS class ที่ไม่มีนิยามใน cssCode)
s.vsCellStyle = (rec, name) => {
  const cls = name === 'bp' ? s.bpClassForRec(rec) : s.vsClassForRec(rec, name)
  if (cls === 'is-danger') return 'color:var(--el-color-danger);font-weight:600;'
  if (cls === 'is-warning') return 'color:var(--el-color-warning);font-weight:600;'
  return ''
}

s.loadVs = () => {
  s.vsRec = null
  const visitId = s.tran && s.tran.vid && s.tran.vid.value
  if (!visitId) return
  field.getFormRef().userState.crudGetAll({
    sdProvider: {
      providerId: '6a470b4939179670f85ba2d8',   // ฟอร์ม Vital Sign
      providerType: 'FORM',
      params: { vid: String(visitId) },
      options: {
        where: "`vid.value` = CONVERT(:vid, 'objectId')",
        orderBy: [{ column: 'created_at', sort: 'DESC' }],
        limit: 1,
        page: 1
      }
    },
    totalEnable: false
  }, (res) => { s.vsRec = (res.data && res.data[0]) || null })
}

// เปิดฟอร์ม Vital Sign — dataId null = เพิ่มใหม่ (parent = visit), มีค่า = แก้ตัวล่าสุด
s.openVs = (dataId) => {
  const visitId = s.tran && s.tran.vid && s.tran.vid.value
  if (!visitId) { field.alert('ไม่พบ visit', 'warning'); return }
  const form = field.getFormRef()
  form.openForm('6a470b4939179670f85ba2d8', dataId ? String(dataId) : null, String(visitId), null, {
    afterSaveCallback: () => { form.subFormClose(); s.loadVs() }
  })
}

// ---- ประวัติ Vital Sign — ข้าม visit ของคนไข้คนนี้ (กรองด้วย vid.xtbxlv1_xfx_id = person id) ----
s.vsHistory = null
s.vsFilterOptions = [
  { label: '1 เดือน', type: 'months', value: 1 },
  { label: '3 เดือน', type: 'months', value: 3 },
  { label: '9 เดือน', type: 'months', value: 9 },
  { label: '1 ปี', type: 'months', value: 12 },
  { label: '2 ปี', type: 'months', value: 24 },
  { label: '3 ปี', type: 'months', value: 36 }
]
s.vsCountFilterOptions = [
  { label: '5 ครั้ง', type: 'count', value: 5 },
  { label: '10 ครั้ง', type: 'count', value: 10 },
  { label: '20 ครั้ง', type: 'count', value: 20 }
]
s.vsFilterMode = { type: 'months', value: 3 }
s.setVsFilter = (type, value) => { s.vsFilterMode = { type: type, value: value } }
s.loadVsHistory = () => {
  const personId = s.tran && s.tran.vid && s.tran.vid.xtbxlv1_xfx_id
  if (!personId) { field.alert('ไม่พบข้อมูลผู้ป่วย', 'warning'); return }
  s.vsHistory = null
  field.getFormRef().userState.crudGetAll({
    sdProvider: {
      providerId: '6a470b4939179670f85ba2d8',
      providerType: 'FORM',
      params: { pid: String(personId) },
      options: {
        where: "`vid.xtbxlv1_xfx_id` = CONVERT(:pid, 'objectId')",
        orderBy: [{ column: 'created_at', sort: 'ASC' }],
        limit: 200,
        page: 1
      }
    },
    totalEnable: false
  }, (res) => { s.vsHistory = res.data || [] })
}

// ---- ประวัติ BMI — ข้าม visit ของคนไข้คนนี้ ----
s.bmiHistory = null
s.loadBmiHistory = () => {
  const personId = s.tran && s.tran.vid && s.tran.vid.xtbxlv1_xfx_id
  if (!personId) { field.alert('ไม่พบข้อมูลผู้ป่วย', 'warning'); return }
  s.bmiHistory = null
  field.getFormRef().userState.crudGetAll({
    sdProvider: {
      providerId: '6a4689ef39179670f85ba2a2',
      providerType: 'FORM',
      params: { pid: String(personId) },
      options: {
        where: "`vid.xtbxlv1_xfx_id` = CONVERT(:pid, 'objectId')",
        orderBy: [{ column: 'created_at', sort: 'ASC' }],
        limit: 30,
        page: 1
      }
    },
    totalEnable: false
  }, (res) => { s.bmiHistory = res.data || [] })
}

// ---- รวมประวัติ Vital Sign + BMI เข้าด้วยกัน โดย group ตาม visit (vid.value) ----
s.historyByVisit = () => {
  try {
    const map = {}
    const addRec = (rec, kind) => {
      if (!rec || !rec.vid || !rec.vid.value) return
      const vid = String(rec.vid.value)
      if (!map[vid]) {
        map[vid] = {
          visitId: vid,
          visitDate: rec.vid.visit_date || (rec.created_at || '').slice(0, 10),
          vn: rec.vid.vn || '-',
          vs: null,
          bmi: null,
          ts: rec.created_at || ''
        }
      }
      map[vid][kind] = rec
      if (String(rec.created_at || '') > map[vid].ts) map[vid].ts = rec.created_at
    }
    ;(s.vsHistory || []).forEach((r) => addRec(r, 'vs'))
    ;(s.bmiHistory || []).forEach((r) => addRec(r, 'bmi'))
    return Object.values(map).sort((a, b) => String(b.ts).localeCompare(String(a.ts)))   // ใหม่สุดก่อน
  } catch (e) {
    console.error('[opd_card] historyByVisit failed:', e)
    return []
  }
}

// ---- History รวม (Vital Sign + BMI) — เปิดจากไอคอน TrendCharts ข้างดินสอ BMI/Vital Sign, โหลดทั้งคู่พร้อมกัน ----
s.historyVisible = false
s.openHistory = () => { s.historyVisible = true; s.loadVsHistory(); s.loadBmiHistory() }
s.closeHistory = () => { s.historyVisible = false }   // เรียกจากปุ่ม ✕ ในกล่อง overlay เอง (เลิกใช้ el-dialog แล้ว กัน crash)

// ---- กราฟแนวโน้มแยกราย metric — วาด SVG เอง (ไม่มี chart library ใน sandbox ของ vue-ui) ----
s.svgLineChart = (series, labels, unit) => {
  const W = 500, H = 130, padL = 34, padR = 10, padT = 10, padB = 20
  const innerW = W - padL - padR, innerH = H - padT - padB
  const vals = series.reduce((a, sr) => a.concat(sr.values.filter((v) => v != null)), [])
  if (!vals.length) return '<div style="text-align:center;padding:16px;color:var(--el-text-color-secondary);font-size:13px;">ยังไม่มีข้อมูล</div>'
  let min = Math.min(...vals), max = Math.max(...vals)
  if (min === max) { min -= 1; max += 1 }
  const pad = (max - min) * 0.15
  min -= pad; max += pad
  const n = labels.length
  const xAt = (i) => padL + (n <= 1 ? innerW / 2 : (innerW * i) / (n - 1))
  const yAt = (v) => padT + innerH - ((v - min) / (max - min)) * innerH
  let svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" style="width:100%;height:' + H + 'px;display:block;">'
  for (let g = 0; g < 3; g++) {
    const gy = padT + (innerH * g) / 2
    const gv = (max - ((max - min) * g) / 2).toFixed(1)
    svg += '<line x1="' + padL + '" y1="' + gy + '" x2="' + (W - padR) + '" y2="' + gy + '" stroke="var(--el-border-color-lighter)" stroke-width="1"/>'
    svg += '<text x="2" y="' + (gy + 3) + '" font-size="9" fill="var(--el-text-color-secondary)">' + gv + '</text>'
  }
  labels.forEach((lb, i) => {
    if (n > 1 && i % Math.ceil(n / 6) !== 0 && i !== n - 1) return
    svg += '<text x="' + xAt(i) + '" y="' + (H - 4) + '" font-size="9" fill="var(--el-text-color-secondary)" text-anchor="middle">' + lb + '</text>'
  })
  series.forEach((sr) => {
    const segs = []
    let cur = []
    sr.values.forEach((v, i) => {
      if (v == null) { if (cur.length) { segs.push(cur); cur = [] } return }
      cur.push(xAt(i) + ',' + yAt(v))
    })
    if (cur.length) segs.push(cur)
    segs.forEach((seg) => { svg += '<polyline points="' + seg.join(' ') + '" fill="none" stroke="' + sr.color + '" stroke-width="2"/>' })
    sr.values.forEach((v, i) => {
      if (v == null) return
      svg += '<circle cx="' + xAt(i) + '" cy="' + yAt(v) + '" r="3" fill="' + sr.color + '"><title>' + sr.name + ': ' + v + (unit || '') + '</title></circle>'
    })
  })
  svg += '</svg>'
  return svg
}
s.chartLegend = (series) => series.map((sr) => '<span style="display:inline-flex;align-items:center;gap:4px;margin-right:12px;font-size:12px;color:var(--el-text-color-regular);"><span style="width:9px;height:9px;border-radius:50%;background:' + sr.color + ';display:inline-block;"></span>' + sr.name + '</span>').join('')

// ---- กราฟ BMI (weight/stature/BMI) — เปิดจากไอคอน TrendCharts ข้างดินสอ BMI ----
s.bmiChartVisible = false
s.bmiApexInstance = null
s.bmiChartElNode = null
s.openBmiChart = () => { s.bmiChartVisible = true; s.loadBmiHistory() }
s.closeBmiChart = () => {
  s.bmiChartVisible = false
  if (s.bmiApexInstance) { s.bmiApexInstance.destroy(); s.bmiApexInstance = null }
  s.bmiChartElNode = null
}
s.bmiChartElMounted = (vnode) => {
  s.bmiChartElNode = (vnode && vnode.el) || null
  s.bmiApexLoadTries = 0
  s.mountBmiChart()
}
s.bmiChartElUnmounted = () => {
  if (s.bmiApexInstance) { s.bmiApexInstance.destroy(); s.bmiApexInstance = null }
  s.bmiChartElNode = null
}

// ---- WHO BMI-for-age LMS (0-19y, ชาย/หญิง) — ของจริงจาก WHO Child Growth Standards (0-5y) +
// WHO Growth Reference (5-19y), ดึงจาก cdn.who.int แล้ว cross-check บิตต่อบิตกับ WHO GitHub source
// (anthro/anthroplus) ไม่ใช่ตัวเลขประมาณ — sampled ทุก 1 ด. (0-24), 3 ด. (24-60), 6 ด. (60-228)
// แต่ละแถว [age_months, L, M, S] ต่อจุด ใช้สูตร LMS มาตรฐานแปลงเป็นเส้น percentile ใดก็ได้
s.WHO_BMI_LMS = {
